select case when year(s.opened_date) < 2024 then 'before_2024' when year(s.opened_date) = 2024 then '2024' else 'after_2024' end as opened_cohort, max(p.amount) - min(p.amount) as amount_range, count(distinct p.amount) as unique_statuss from payments p inner join orders o on p.order_id = o.id full outer join stores s on o.store_id = s.id where s.store_name not like 'Sia%' group by case when year(s.opened_date) < 2024 then 'before_2024' when year(s.opened_date) = 2024 then '2024' else 'after_2024' end;
